@dataclass(frozen=True)
class Beat:
    place: str
    weather: str
    object: str
    public: str
    secret: str
    ally: str
    threat: str
    memory: str
    question: str
    line: str
    turn: str
    image: str

@dataclass(frozen=True)
class Chapter:
    number: int
    title: str
    dateline: str
    location: str
    purpose: str
    beats: tuple[Beat, ...]


def B(place, weather, object, public, secret, ally, threat, memory, question, line, turn, image):
    return Beat(place, weather, object, public, secret, ally, threat, memory, question, line, turn, image)


